package com.boosticon;

import java.awt.Color;
import net.runelite.client.config.Alpha;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;
import net.runelite.client.config.Keybind;
import net.runelite.client.config.Range;

@ConfigGroup(BoostIconConfig.GROUP)
public interface BoostIconConfig extends Config
{
	String GROUP = "boostIconPlugin";

	@ConfigSection(
		name = "Stats",
		description = "Which combat stats get an icon.",
		position = 100
	)
	String statsSection = "stats";

	@Range(min = -12, max = 100)
	@ConfigItem(
		keyName = "size",
		name = "Size",
		description = "Adjust the size of the icons. Below zero for smaller than they are now.",
		position = 1
	)
	default int size()
	{
		return 0;
	}

	@Range(min = -200, max = 200)
	@ConfigItem(
		keyName = "drop",
		name = "Lower by",
		description = "How far below the health bar the icons sit. Below zero puts them above it.",
		position = 2
	)
	default int drop()
	{
		return 20;
	}

	@ConfigItem(
		keyName = "anchor",
		name = "Anchor",
		description = "What the icons are measured from: the player's head, middle or feet.",
		position = 3
	)
	default IconAnchor iconAnchor()
	{
		return IconAnchor.TOP;
	}

	@ConfigItem(
		keyName = "position",
		name = "Icon position",
		description = "Change what side of the HP bar the icons appear.",
		position = 4
	)
	default IconSide iconSide()
	{
		return IconSide.RIGHT;
	}

	@ConfigItem(
		keyName = "statText",
		name = "Show",
		description = "What to write next to each icon. Hitpoints, prayer and special attack always read as how much is left.",
		position = 5
	)
	default StatText statText()
	{
		return StatText.CHANGE;
	}

	@ConfigItem(
		keyName = "showBuffs",
		name = "Show buffs",
		description = "Show stats that are above their real level.",
		position = 6
	)
	default boolean showBuffs()
	{
		return true;
	}

	@ConfigItem(
		keyName = "showDebuffs",
		name = "Show debuffs",
		description = "Show stats that are below their real level.",
		position = 7
	)
	default boolean showDebuffs()
	{
		return true;
	}

	@ConfigItem(
		keyName = "showUnchanged",
		name = "Show unpotted",
		description = "Show stats that are sitting at their real level. Hitpoints, prayer and special attack always show, since a full bar is worth seeing.",
		position = 8
	)
	default boolean showUnchanged()
	{
		return false;
	}

	@Range(max = 100)
	@ConfigItem(
		keyName = "opacity",
		name = "Opacity",
		description = "How solid the icons and numbers are drawn. 100 is solid and 0 is invisible.",
		position = 9
	)
	default int opacity()
	{
		return 100;
	}

	@Alpha
	@ConfigItem(
		keyName = "buffColor",
		name = "Buff colour",
		description = "Colour of the number on a buffed stat.",
		position = 10
	)
	default Color buffColor()
	{
		return Color.GREEN;
	}

	@Alpha
	@ConfigItem(
		keyName = "debuffColor",
		name = "Debuff colour",
		description = "Colour of the number on a debuffed stat.",
		position = 11
	)
	default Color debuffColor()
	{
		return new Color(238, 51, 51);
	}

	@Alpha
	@ConfigItem(
		keyName = "expiringColor",
		name = "Running out colour",
		description = "Colour of the number once a buff is down to its last few levels.",
		position = 12
	)
	default Color expiringColor()
	{
		return Color.YELLOW;
	}

	@Alpha
	@ConfigItem(
		keyName = "unchangedColor",
		name = "Unpotted colour",
		description = "Colour of the number on a stat that is at its real level.",
		position = 13
	)
	default Color unchangedColor()
	{
		return Color.WHITE;
	}

	@Range(max = 99)
	@ConfigItem(
		keyName = "buffThreshold",
		name = "Buff threshold",
		description = "How many levels a buff has left for it to count as running out. 0 for never.",
		position = 14
	)
	default int buffThreshold()
	{
		return 3;
	}

	@Range(max = 100)
	@ConfigItem(
		keyName = "lowHp",
		name = "Low HP",
		description = "Hitpoints or prayer below this much of the full amount turn the running out colour.",
		position = 15
	)
	default int lowHp()
	{
		return 60;
	}

	@Range(max = 100)
	@ConfigItem(
		keyName = "criticalHp",
		name = "Critical HP",
		description = "Hitpoints or prayer below this much of the full amount turn the debuff colour.",
		position = 16
	)
	default int criticalHp()
	{
		return 35;
	}

	@ConfigItem(
		keyName = "showSelf",
		name = "Show on yourself",
		description = "Show your own boosted and drained stats over your head.",
		position = 17
	)
	default boolean showSelf()
	{
		return true;
	}

	@ConfigItem(
		keyName = "partyStats",
		name = "Party stats",
		description = "Show your party's boosted and drained stats over their heads. Hitpoints, prayer and special attack come from anyone running the client's Party plugin. The rest needs this plugin on their end too.",
		position = 18
	)
	default boolean partyStats()
	{
		return false;
	}

	@ConfigItem(
		keyName = "toggle",
		name = "Toggle",
		description = "A key that turns the icons off and back on. Unassigned to start with.",
		position = 19
	)
	default Keybind toggle()
	{
		return Keybind.NOT_SET;
	}

	@ConfigItem(
		keyName = "showAttack",
		name = "Attack",
		description = "Show an icon when Attack is boosted or drained.",
		section = statsSection,
		position = 101
	)
	default boolean showAttack()
	{
		return true;
	}

	@ConfigItem(
		keyName = "showStrength",
		name = "Strength",
		description = "Show an icon when Strength is boosted or drained.",
		section = statsSection,
		position = 102
	)
	default boolean showStrength()
	{
		return true;
	}

	@ConfigItem(
		keyName = "showDefence",
		name = "Defence",
		description = "Show an icon when Defence is boosted or drained.",
		section = statsSection,
		position = 103
	)
	default boolean showDefence()
	{
		return true;
	}

	@ConfigItem(
		keyName = "showRanged",
		name = "Ranged",
		description = "Show an icon when Ranged is boosted or drained.",
		section = statsSection,
		position = 104
	)
	default boolean showRanged()
	{
		return true;
	}

	@ConfigItem(
		keyName = "showMagic",
		name = "Magic",
		description = "Show an icon when Magic is boosted or drained.",
		section = statsSection,
		position = 105
	)
	default boolean showMagic()
	{
		return true;
	}

	@ConfigItem(
		keyName = "showPrayer",
		name = "Prayer",
		description = "Show an icon for your prayer points. Off by default, since the orb already shows them.",
		section = statsSection,
		position = 106
	)
	default boolean showPrayer()
	{
		return false;
	}

	@ConfigItem(
		keyName = "showHitpoints",
		name = "Hitpoints",
		description = "Show an icon for your hitpoints. Off by default, since the orb already shows them.",
		section = statsSection,
		position = 107
	)
	default boolean showHitpoints()
	{
		return false;
	}

	@ConfigItem(
		keyName = "showSpecial",
		name = "Special attack",
		description = "Show an icon for your special attack energy. Off by default, since the orb already shows it.",
		section = statsSection,
		position = 108
	)
	default boolean showSpecial()
	{
		return false;
	}
}

package com.boosticon;

import java.awt.Color;
import java.awt.Composite;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import java.util.Arrays;
import java.util.List;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.Perspective;
import net.runelite.api.Player;
import net.runelite.api.Point;
import net.runelite.api.WorldView;
import net.runelite.api.coords.LocalPoint;
import net.runelite.client.game.SpriteManager;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.util.ImageUtil;

public class BoostIconOverlay extends Overlay
{
	/**
	 * How far from the middle of your health bar the column of icons sits, and how far past that the
	 * number goes.
	 */
	private static final int ICON_OFFSET = 25;

	private static final int TEXT_OFFSET = 45;

	/**
	 * How tall an icon is drawn before the size setting, which is smaller than the skills tab draws them.
	 */
	private static final int BASE_HEIGHT = 16;

	/**
	 * How light a pixel has to be to want an outline pixel of its own next to it. The skill icons are
	 * drawn with a dark edge already, and going around that as well is what reads as two pixels thick.
	 */
	private static final int DARK = 48;

	/**
	 * How opaque a pixel has to be to count as part of the icon rather than as room around it, so that
	 * the edge of one is in a definite place for the outline to go around.
	 */
	private static final int SOLID = 128;

	private final Client client;
	private final SpriteManager spriteManager;
	private final BoostIconPlugin plugin;

	/**
	 * The outlined icons, by {@link CombatStat} ordinal, since outlining one is work that only has to
	 * happen once, and finding it again is work for every stat of every player, every frame.
	 */
	private final BufferedImage[] icons = new BufferedImage[CombatStat.ALL.length];

	/**
	 * The height those were prepared at, since a change to the size setting makes them all over again.
	 */
	private int iconHeight;

	/**
	 * The font the overlay was last handed and the size it was last grown by, so that growing it again is
	 * work for a change of setting rather than for every frame.
	 */
	private Font given;
	private int givenSize;
	private Font grown;

	/**
	 * How wide and how tall that font draws, which the client works out behind a lock, so it is asked
	 * the once along with the font rather than once a frame.
	 */
	private FontMetrics metrics;

	@Inject
	BoostIconOverlay(Client client, SpriteManager spriteManager, BoostIconPlugin plugin)
	{
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_SCENE);
		this.client = client;
		this.spriteManager = spriteManager;
		this.plugin = plugin;
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		List<StatColumn> columns = plugin.getColumns();

		if (columns.isEmpty() || plugin.isHidden())
		{
			return null;
		}

		Settings settings = plugin.getSettings();
		int size = settings.size();

		// Three at the least, since the outline takes a pixel at the top and another at the bottom
		int height = Math.max(3, BASE_HEIGHT + size);

		// Measured the once, since every number in every column is drawn in the same font
		useFont(graphics, size);

		// Put back afterwards, since the graphics goes on to the overlays after this one
		Composite composite = graphics.getComposite();
		graphics.setComposite(settings.composite());

		for (StatColumn column : columns)
		{
			drawColumn(graphics, settings, column, height);
		}

		graphics.setComposite(composite);

		return null;
	}

	private void drawColumn(Graphics2D graphics, Settings settings, StatColumn column, int height)
	{
		Player player = column.getPlayer();
		LocalPoint location = player.getLocalLocation();

		if (location == null)
		{
			return;
		}

		Point middle = middleOf(location, anchor(settings, player));

		if (middle == null)
		{
			return;
		}

		boolean right = settings.right();
		int size = settings.size();

		// The column is drawn upwards from here, so lowering it is taking off the height it starts at
		int adjustIcon = 5 - settings.drop();

		for (StatChange change : column.getChanges())
		{
			BufferedImage icon = icon(change.getStat(), height);

			if (icon == null)
			{
				continue;
			}

			// Hung off the middle of where the column goes, which is half an icon over from its left
			int x = middle.getX() - icon.getWidth() / 2;
			int top = middle.getY() - icon.getHeight() / 2 - adjustIcon;

			// Already the size it is drawn at, so nothing is scaled here
			graphics.drawImage(icon, x + (right ? ICON_OFFSET : -ICON_OFFSET), top, null);

			String label = change.label(settings);

			if (label != null)
			{
				// Written rightwards from where it is put, so the icons being on the left means
				// measuring back from the end of the number instead, or a long one runs into its own
				// icon while a short one sits nowhere near it
				int textX = right
					? x + size + TEXT_OFFSET
					: x + icon.getWidth() - size - TEXT_OFFSET - metrics.stringWidth(label);

				drawOutlined(
					graphics,
					label,
					textX,
					top + (icon.getHeight() + metrics.getAscent()) / 2,
					change.color(settings));
			}

			adjustIcon += icon.getHeight();
		}
	}

	/**
	 * The middle of where a column hangs from, on the canvas. The game's own
	 * {@code Perspective.getCanvasImageLocation} works out this same point and then takes half an image
	 * off it, so the point is worked out once for the whole column here and each icon is put against it
	 * by its own size, rather than projecting the one point again for every icon hanging off it.
	 */
	private Point middleOf(LocalPoint location, int anchor)
	{
		WorldView worldView = client.getWorldView(location.getWorldView());

		return worldView == null
			? null
			: Perspective.localToCanvas(client, location, worldView.getPlane(), anchor);
	}

	/**
	 * Puts the graphics onto the font the numbers are drawn in: the one the overlay was handed, grown by
	 * the size setting. Kept from one frame to the next, along with how it measures, since the overlay is
	 * handed the same font before each of them and the answer only changes when the setting does or the
	 * client is put onto a different font.
	 */
	private void useFont(Graphics2D graphics, int size)
	{
		Font font = graphics.getFont();

		if (font != given || size != givenSize)
		{
			given = font;
			givenSize = size;
			grown = font.deriveFont(font.getStyle(), font.getSize() + size);
			metrics = null;
		}

		graphics.setFont(grown);

		if (metrics == null)
		{
			metrics = graphics.getFontMetrics();
		}
	}

	/**
	 * A number with black put in around it, which is what keeps it readable over whatever the player is
	 * standing on. The same five passes the client's own text component makes, written out here because
	 * that one runs the text past a colour tag pattern on the way, and a number has no tags in it.
	 */
	private static void drawOutlined(Graphics2D graphics, String text, int x, int y, Color color)
	{
		graphics.setColor(Color.BLACK);
		graphics.drawString(text, x, y + 1);
		graphics.drawString(text, x, y - 1);
		graphics.drawString(text, x + 1, y);
		graphics.drawString(text, x - 1, y);
		graphics.setColor(color);
		graphics.drawString(text, x, y);
	}

	/**
	 * How far up the player the column is measured from, which is as tall as the player for the health
	 * bar it normally sits by, and nothing at all for the tile they are standing on.
	 */
	private static int anchor(Settings settings, Player player)
	{
		switch (settings.anchor())
		{
			case BOTTOM:
				return 0;
			case MIDDLE:
				return player.getLogicalHeight() / 2;
			default:
				return player.getLogicalHeight();
		}
	}

	/**
	 * A skill's icon with a black outline around it, which is what keeps it off whatever is behind it.
	 * The outline has to go somewhere, so the sprite is given a pixel of room on each side for it first.
	 */
	private BufferedImage icon(CombatStat stat, int height)
	{
		if (height != iconHeight)
		{
			Arrays.fill(icons, null);
			iconHeight = height;
		}

		BufferedImage icon = icons[stat.ordinal()];

		if (icon != null)
		{
			return icon;
		}

		BufferedImage sprite = spriteManager.getSprite(stat.getSpriteId(), 0);

		if (sprite == null || sprite.getWidth() < 1 || sprite.getHeight() < 1)
		{
			// Still being loaded, so there is nothing to prepare yet
			return null;
		}

		// Scaled before it is outlined, so the outline is a pixel wide at the size it ends up drawn at
		icon = outlined(scaled(sprite, height - 2));

		icons[stat.ordinal()] = icon;

		return icon;
	}

	/**
	 * The sprite at the height the icons are drawn at, keeping its shape, taken a pixel at a time so
	 * that every pixel of it stays the colour it was drawn in. Blending them instead leaves an edge
	 * that fades out over a pixel or two, which is nowhere in particular for an outline to go, and ends
	 * up with the outline showing along some of an icon and not the rest of it.
	 */
	static BufferedImage scaled(BufferedImage sprite, int height)
	{
		if (height == sprite.getHeight())
		{
			return sprite;
		}

		int width = Math.max(1, Math.round(sprite.getWidth() * height / (float) sprite.getHeight()));
		BufferedImage scaled = new BufferedImage(width, height, BufferedImage.TYPE_INT_ARGB);

		for (int x = 0; x < width; x++)
		{
			for (int y = 0; y < height; y++)
			{
				// The middle of what the pixel covers of the sprite, so that it lines up the same way
				// in from either edge
				scaled.setRGB(x, y, sprite.getRGB(
					Math.min((x * 2 + 1) * sprite.getWidth() / (width * 2), sprite.getWidth() - 1),
					Math.min((y * 2 + 1) * sprite.getHeight() / (height * 2), sprite.getHeight() - 1)));
			}
		}

		return scaled;
	}

	/**
	 * Black put in around a sprite, wherever the sprite does not have something dark enough there
	 * already, so the icon ends up with an edge of one pixel all the way round rather than two in the
	 * places the artwork was already outlined.
	 */
	static BufferedImage outlined(BufferedImage sprite)
	{
		int width = sprite.getWidth() + 2;
		int height = sprite.getHeight() + 2;

		// A pixel of room on each side, for the outline to have somewhere to go
		BufferedImage image = ImageUtil.resizeCanvas(sprite, width, height);
		BufferedImage outlined = ImageUtil.resizeCanvas(sprite, width, height);

		for (int x = 0; x < width; x++)
		{
			for (int y = 0; y < height; y++)
			{
				// Read from the sprite throughout, so a pixel just filled in cannot grow the outline
				if (empty(image, x, y) && bordersLight(image, x, y))
				{
					outlined.setRGB(x, y, Color.BLACK.getRGB());
				}
			}
		}

		return outlined;
	}

	private static boolean empty(BufferedImage image, int x, int y)
	{
		return (image.getRGB(x, y) >>> 24) < SOLID;
	}

	/**
	 * Whether any of the eight pixels around this one is part of the icon and light enough to need an
	 * outline of its own.
	 */
	private static boolean bordersLight(BufferedImage image, int x, int y)
	{
		for (int alongX = Math.max(x - 1, 0); alongX <= Math.min(x + 1, image.getWidth() - 1); alongX++)
		{
			for (int alongY = Math.max(y - 1, 0); alongY <= Math.min(y + 1, image.getHeight() - 1); alongY++)
			{
				int pixel = image.getRGB(alongX, alongY);

				if ((pixel >>> 24) >= SOLID && !dark(pixel))
				{
					return true;
				}
			}
		}

		return false;
	}

	private static boolean dark(int pixel)
	{
		int lightest = Math.max((pixel >> 16) & 0xff, Math.max((pixel >> 8) & 0xff, pixel & 0xff));

		return lightest < DARK;
	}
}

package com.boosticon;

import com.google.inject.Provides;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Player;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.events.PartyChanged;
import net.runelite.client.input.KeyManager;
import net.runelite.client.party.PartyMember;
import net.runelite.client.party.PartyService;
import net.runelite.client.party.WSClient;
import net.runelite.client.party.events.UserPart;
import net.runelite.client.party.messages.UserSync;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.plugins.party.messages.StatusUpdate;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.util.HotkeyListener;
import net.runelite.client.util.Text;

@PluginDescriptor(
	name = "Boosted Icon",
	description = "Icons by your health bar for boosted or drained combat stats",
	tags = {"boost", "drain", "potion", "stats", "combat", "party"}
)
public class BoostIconPlugin extends Plugin
{
	private static final CombatStat[] STATS = CombatStat.ALL;

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private BoostIconConfig config;

	@Inject
	private BoostIconOverlay overlay;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private PartyService partyService;

	@Inject
	private WSClient wsClient;

	@Inject
	private KeyManager keyManager;

	/**
	 * Whether the key has been used to put the icons away. Set from the keyboard and read while the
	 * overlay is drawn, which are not the same thread.
	 */
	private volatile boolean hidden;

	private final HotkeyListener toggle = new HotkeyListener(() -> config.toggle())
	{
		@Override
		public void hotkeyPressed()
		{
			hidden = !hidden;
		}
	};

	private final List<StatColumn> columns = new ArrayList<>();

	/**
	 * The settings as they stand, read in one go rather than one at a time while drawing. Replaced rather
	 * than changed when one of them changes, so that whichever thread is reading a set has the whole of
	 * it as it was at one moment.
	 */
	private volatile Settings settings;

	/**
	 * The levels each party member has shared, held until they share different ones or leave.
	 */
	private final Map<Long, PartyLevels> partyLevels = new HashMap<>();

	/**
	 * What was last sent to the party, so a tick that changed nothing sends nothing.
	 */
	private String sentName;
	private int[] sentBoosted;
	private int[] sentReal;

	@Override
	protected void startUp()
	{
		settings = new Settings(config);
		overlayManager.add(overlay);
		keyManager.registerKeyListener(toggle);
		wsClient.registerMessage(BoostIconStats.class);
	}

	@Override
	protected void shutDown()
	{
		overlayManager.remove(overlay);
		keyManager.unregisterKeyListener(toggle);
		hidden = false;
		wsClient.unregisterMessage(BoostIconStats.class);

		// A plugin is stopped on the Swing thread, while everything it has read of the game is written
		// and read a tick at a time on the client's own. Letting go of it over there keeps all of it to
		// the one thread, rather than emptying a list the tick in flight is still walking through
		clientThread.invoke(() ->
		{
			columns.clear();
			partyLevels.clear();
			forgetSent();
		});
	}

	@Provides
	BoostIconConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(BoostIconConfig.class);
	}

	/**
	 * Whether the icons have been put away with the toggle key, which stops them being drawn and
	 * nothing else: levels are still kept up to date and still shared with the party.
	 */
	boolean isHidden()
	{
		return hidden;
	}

	/**
	 * The icons to draw this tick. The overlay reads this on the same thread that fills it in, and is
	 * handed the list itself rather than a wrapper around it, which would be an object made for every
	 * frame to hold something that is only ever read.
	 */
	List<StatColumn> getColumns()
	{
		return columns;
	}

	/**
	 * The settings as they stand, for the overlay to draw a whole frame by.
	 */
	Settings getSettings()
	{
		return settings;
	}

	/**
	 * Levels arrive with the rest of the tick, and a boost that wears off is a tick's news as well, so
	 * the whole set is read fresh each tick rather than followed through stat change events. Nothing to
	 * get out of step with, and a party member's levels are treated the same way.
	 */
	@Subscribe
	public void onGameTick(GameTick event)
	{
		Settings settings = this.settings;

		columns.clear();

		int[] boosted = new int[STATS.length];
		int[] real = new int[STATS.length];

		for (int i = 0; i < STATS.length; i++)
		{
			boosted[i] = now(STATS[i]);
			real[i] = full(STATS[i]);
		}

		if (settings.showSelf())
		{
			addColumn(settings, client.getLocalPlayer(), boosted, real);
		}

		share(settings, boosted, real);

		if (!settings.partyStats() || !partyService.isInParty())
		{
			partyLevels.clear();
			return;
		}

		if (partyLevels.isEmpty())
		{
			// Nobody has shared anything, so there is nobody to go looking for among the players around
			return;
		}

		Map<String, Player> nearby = playersByName();
		PartyMember local = partyService.getLocalMember();

		for (PartyMember member : partyService.getMembers())
		{
			if (local != null && member.getMemberId() == local.getMemberId())
			{
				continue;
			}

			PartyLevels levels = partyLevels.get(member.getMemberId());

			if (levels == null)
			{
				continue;
			}

			String name = nameOf(member, levels);

			if (name == null)
			{
				continue;
			}

			addColumn(settings, nearby.get(Text.standardize(name)), levels.getBoosted(), levels.getReal());
		}
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() != GameState.LOGGED_IN)
		{
			columns.clear();
			forgetSent();
		}
	}

	/**
	 * Levels belong to the party they were shared with, and a different party is different people.
	 */
	@Subscribe
	public void onPartyChanged(PartyChanged event)
	{
		clientThread.invoke(() ->
		{
			partyLevels.clear();
			forgetSent();
		});

		requestSync();
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (!BoostIconConfig.GROUP.equals(event.getGroup()))
		{
			return;
		}

		// Read again here rather than while drawing, so that a change shows on the next frame either way
		settings = new Settings(config);

		if ("partyStats".equals(event.getKey()))
		{
			requestSync();
		}
	}

	@Subscribe
	public void onBoostIconStats(BoostIconStats message)
	{
		int[] boosted = message.getBoosted();
		int[] real = message.getReal();

		if (boosted == null || real == null
			|| boosted.length != STATS.length || real.length != STATS.length)
		{
			return;
		}

		long memberId = message.getMemberId();
		String name = message.getName();

		if (!settings.partyStats())
		{
			return;
		}

		clientThread.invoke(() ->
		{
			if (isOwn(memberId))
			{
				return;
			}

			PartyLevels levels = levelsFor(memberId);

			if (name != null && !name.isEmpty())
			{
				levels.setName(name);
			}

			for (int i = 0; i < STATS.length; i++)
			{
				set(levels, STATS[i], boosted[i], real[i]);
			}
		});
	}

	@Subscribe
	public void onUserPart(UserPart event)
	{
		clientThread.invoke(() -> partyLevels.remove(event.getMemberId()));
	}

	/**
	 * Somebody has just joined and has nothing of anyone's yet, so the next tick sends again.
	 */
	@Subscribe
	public void onUserSync(UserSync event)
	{
		clientThread.invoke(this::forgetSent);
	}

	/**
	 * What the client's own party plugin already shares, which covers hitpoints, prayer and special
	 * attack for anyone running it, with or without this plugin. A status carries only the parts of
	 * itself that changed, so each half of each stat is taken on its own and the rest of what is known
	 * about that member is left as it was.
	 */
	@Subscribe
	public void onStatusUpdate(StatusUpdate event)
	{
		long memberId = event.getMemberId();

		if (!settings.partyStats())
		{
			return;
		}

		Integer spec = event.getSpecEnergy();

		clientThread.invoke(() ->
		{
			if (isOwn(memberId))
			{
				return;
			}

			PartyLevels levels = levelsFor(memberId);

			set(levels, CombatStat.HITPOINTS, event.getHealthCurrent(), event.getHealthMax());
			set(levels, CombatStat.PRAYER, event.getPrayerCurrent(), event.getPrayerMax());

			// A bar is full at the same amount for everyone, so it is known as soon as the amount is
			set(levels, CombatStat.SPECIAL, spec, spec == null ? null : CombatStat.FULL_PERCENT);
		});
	}

	/**
	 * One stat out of a status, where either half can be missing because it had not changed. Levels
	 * come from whoever is sharing them and are taken as nothing more than numbers, so anything a stat
	 * could not be at is dropped rather than drawn.
	 */
	private static void set(PartyLevels levels, CombatStat stat, Integer boostedLevel, Integer realLevel)
	{
		if (boostedLevel != null && stat.isPossibleNow(boostedLevel))
		{
			levels.setBoosted(stat, boostedLevel);
		}

		if (realLevel != null && stat.isPossibleReal(realLevel))
		{
			levels.setReal(stat, realLevel);
		}
	}

	/**
	 * The name of the player a party member is playing as. The party itself knows them by an id and
	 * nothing more: a name is put to one by the party plugin that comes with the client, and only while
	 * that plugin is running, so what a member shared of their own name comes first. That is what lets
	 * the icons appear for a team running this plugin and not that one.
	 */
	private static String nameOf(PartyMember member, PartyLevels levels)
	{
		String shared = levels.getName();

		if (shared != null)
		{
			return shared;
		}

		// Set alongside the name by the party plugin, so a member it has not named is a member still
		// going by the stand-in name every member starts out with
		return member.isLoggedIn() ? member.getDisplayName() : null;
	}

	/**
	 * Whether a member id is our own. Our levels are read from the client rather than taken off the
	 * party, so our own share of them coming back around is dropped.
	 */
	private boolean isOwn(long memberId)
	{
		PartyMember local = partyService.getLocalMember();

		return local != null && local.getMemberId() == memberId;
	}

	private PartyLevels levelsFor(long memberId)
	{
		return partyLevels.computeIfAbsent(memberId, id -> new PartyLevels());
	}

	/**
	 * Asks the party for the levels it has now, rather than waiting on everyone's next change.
	 */
	void requestSync()
	{
		if (settings.partyStats() && partyService.isInParty())
		{
			partyService.send(new UserSync());
		}
	}

	/**
	 * What the stat is at now. Special attack is not a skill and is kept in tenths of a per cent, which
	 * is finer than anything read off it here, so it is taken down to whole per cent.
	 */
	private int now(CombatStat stat)
	{
		return stat.isPercent()
			? client.getVarpValue(VarPlayerID.SA_ENERGY) / 10
			: client.getBoostedSkillLevel(stat.getSkill());
	}

	/**
	 * What the stat sits at with nothing acting on it, which for special attack is a full bar.
	 */
	private int full(CombatStat stat)
	{
		return stat.isPercent() ? CombatStat.FULL_PERCENT : client.getRealSkillLevel(stat.getSkill());
	}

	private void addColumn(Settings settings, Player player, int[] boosted, int[] real)
	{
		if (player == null || player.getLocalLocation() == null)
		{
			return;
		}

		List<StatChange> changes = null;

		for (int i = 0; i < STATS.length; i++)
		{
			CombatStat stat = STATS[i];

			if (boosted[i] == PartyLevels.UNKNOWN || real[i] == PartyLevels.UNKNOWN)
			{
				continue;
			}

			if (!settings.isEnabled(i))
			{
				continue;
			}

			int change = boosted[i] - real[i];

			// Hitpoints, prayer and special attack are an amount rather than a boost or a drain, so
			// having turned one on is asking to see it, full bar and all
			if (!stat.isPoints()
				&& ((change == 0 && !settings.showUnchanged())
				|| (change > 0 && !settings.showBuffs())
				|| (change < 0 && !settings.showDebuffs())))
			{
				continue;
			}

			if (changes == null)
			{
				// Left until there is something to put in it, since most ticks of most players have
				// nothing off its level at all
				changes = new ArrayList<>(STATS.length);
			}

			changes.add(new StatChange(stat, boosted[i], change));
		}

		if (changes != null)
		{
			columns.add(new StatColumn(player, changes));
		}
	}

	private void share(Settings settings, int[] boosted, int[] real)
	{
		if (!settings.partyStats() || !partyService.isInParty())
		{
			forgetSent();
			return;
		}

		Player local = client.getLocalPlayer();
		String name = local == null ? null : local.getName();

		if (Objects.equals(name, sentName)
			&& Arrays.equals(boosted, sentBoosted) && Arrays.equals(real, sentReal))
		{
			return;
		}

		sentName = name;
		sentBoosted = boosted.clone();
		sentReal = real.clone();
		partyService.send(new BoostIconStats(sentName, sentBoosted, sentReal));
	}

	private void forgetSent()
	{
		sentName = null;
		sentBoosted = null;
		sentReal = null;
	}

	/**
	 * The players around you, by the name the party knows them as. Built once a tick rather than looked
	 * through again for each party member, since a busy world is a great many names to go over.
	 */
	private Map<String, Player> playersByName()
	{
		Map<String, Player> players = new HashMap<>();

		for (Player player : client.getTopLevelWorldView().players())
		{
			String name = player.getName();

			if (name != null)
			{
				// The first of them, as a name is only shared by a player and whatever is mimicking them
				players.putIfAbsent(Text.standardize(name), player);
			}
		}

		return players;
	}
}

package com.boosticon;

import com.google.gson.annotations.SerializedName;
import lombok.EqualsAndHashCode;
import lombok.Value;
import net.runelite.client.party.messages.PartyMemberMessage;

/**
 * Combat stats for a party that has nobody sharing levels already, as levels rather than as the boosts
 * and drains worked out from them, so everyone's own settings decide what they see of them. Named after
 * the plugin because every message on the party connection has to be named differently to every other
 * plugin's.
 */
@Value
@EqualsAndHashCode(callSuper = true)
public class BoostIconStats extends PartyMemberMessage
{
	/**
	 * The name of the player the levels belong to. The party knows its members by an id and nothing else,
	 * and the only thing that ever puts a name to one is the party plugin that comes with the client, so
	 * the name travels with the levels rather than there being no way to place them without that plugin.
	 */
	@SerializedName("n")
	String name;

	/**
	 * The level each combat stat is at now, in {@link CombatStat} order.
	 */
	@SerializedName("b")
	int[] boosted;

	/**
	 * The level each one would be at with nothing acting on it, in the same order.
	 */
	@SerializedName("r")
	int[] real;
}

package com.boosticon;

import java.util.function.Predicate;
import net.runelite.api.Skill;
import net.runelite.api.gameval.SpriteID;

/**
 * The seven skills that make up your combat level, in the order they sit in the stats tab, each with
 * the stats tab icon the game draws for it, and special attack, which is not a skill but runs down and
 * comes back the way the points among them do.
 */
enum CombatStat
{
	ATTACK(Skill.ATTACK, SpriteID.Staticons.ATTACK, BoostIconConfig::showAttack),
	STRENGTH(Skill.STRENGTH, SpriteID.Staticons.STRENGTH, BoostIconConfig::showStrength),
	DEFENCE(Skill.DEFENCE, SpriteID.Staticons.DEFENCE, BoostIconConfig::showDefence),
	RANGED(Skill.RANGED, SpriteID.Staticons.RANGED, BoostIconConfig::showRanged),
	PRAYER(Skill.PRAYER, SpriteID.Staticons.PRAYER, BoostIconConfig::showPrayer),
	MAGIC(Skill.MAGIC, SpriteID.Staticons.MAGIC, BoostIconConfig::showMagic),
	HITPOINTS(Skill.HITPOINTS, SpriteID.Staticons.HITPOINTS, BoostIconConfig::showHitpoints),
	SPECIAL(null, SpriteID.OrbIcon.SPECIAL, BoostIconConfig::showSpecial);

	/**
	 * A full special attack bar. It is kept as a share of one rather than as a level, so this is the
	 * most there can be of it.
	 */
	static final int FULL_PERCENT = 100;

	/**
	 * Every stat, in order. Kept rather than asked for each time, since asking hands out a fresh copy of
	 * the list and this is walked for every player, every tick.
	 */
	static final CombatStat[] ALL = values();

	private final Skill skill;
	private final int spriteId;
	private final Predicate<BoostIconConfig> enabled;

	CombatStat(Skill skill, int spriteId, Predicate<BoostIconConfig> enabled)
	{
		this.skill = skill;
		this.spriteId = spriteId;
		this.enabled = enabled;
	}

	/**
	 * The skill this stat is, or nothing where it is not a skill at all, as special attack is not.
	 */
	Skill getSkill()
	{
		return skill;
	}

	int getSpriteId()
	{
		return spriteId;
	}

	boolean isEnabled(BoostIconConfig config)
	{
		return enabled.test(config);
	}

	/**
	 * Whether the stat is points that run down and get topped up again rather than a level that sits
	 * where it is until something acts on it. How much of these is left matters more than how far they
	 * are from the level, so they are read and coloured that way.
	 */
	boolean isPoints()
	{
		return this == HITPOINTS || this == PRAYER || this == SPECIAL;
	}

	/**
	 * Whether the stat is a share of a full bar rather than a level, which special attack alone is.
	 */
	boolean isPercent()
	{
		return this == SPECIAL;
	}

	/**
	 * Whether a number is one this stat could be sitting at, so that nothing is made of a stat arriving
	 * from elsewhere as something it cannot be. Nought is where a spec leaves the bar and where a prayer
	 * runs out, so it is somewhere a stat really is rather than a number to throw away.
	 */
	boolean isPossibleNow(int level)
	{
		return level >= 0 && (!isPercent() || level <= FULL_PERCENT);
	}

	/**
	 * Whether a number is one this stat could be at with nothing acting on it. That is a level, and a
	 * level is at least one, which is the whole of the difference from the amount above.
	 */
	boolean isPossibleReal(int level)
	{
		return level >= 1 && (!isPercent() || level <= FULL_PERCENT);
	}
}

