package com.boosticon;

import java.util.Arrays;

/**
 * What a party member last told the party about themselves. Levels arrive a stat at a time, as and when
 * each one changes, so every stat is kept until something newer arrives for it.
 */
class PartyLevels
{
	/**
	 * Nothing heard about a stat yet. Below zero, since an empty special attack bar is a real nought.
	 */
	static final int UNKNOWN = -1;

	private static final int SIZE = CombatStat.ALL.length;

	private final int[] boosted = new int[SIZE];
	private final int[] real = new int[SIZE];

	/**
	 * The name of the player the levels belong to, as the member sharing them gave it, or nothing while
	 * they have not said. It is what ties the levels to somebody on screen.
	 */
	private String name;

	PartyLevels()
	{
		Arrays.fill(boosted, UNKNOWN);
		Arrays.fill(real, UNKNOWN);
	}

	void setBoosted(CombatStat stat, int boostedLevel)
	{
		boosted[stat.ordinal()] = boostedLevel;
	}

	void setReal(CombatStat stat, int realLevel)
	{
		real[stat.ordinal()] = realLevel;
	}

	int[] getBoosted()
	{
		return boosted;
	}

	int[] getReal()
	{
		return real;
	}

	void setName(String name)
	{
		this.name = name;
	}

	String getName()
	{
		return name;
	}
}

package com.boosticon;

import java.awt.AlphaComposite;
import java.awt.Color;
import java.awt.Composite;

/**
 * Everything the plugin draws by, read off the settings in one go.
 *
 * A setting costs a lookup and a parse every time it is asked for, which is nothing once and a great
 * deal of nothing for every stat of every player on the screen, every frame. So the whole set is taken
 * here instead, and taken again whenever one of them changes, which leaves a frame costing nothing in
 * settings at all. Held onto and handed about rather than changed in place, so that the party thread
 * reading one of these is reading a set that all came from the same moment.
 */
class Settings
{
	private final int size;
	private final int drop;
	private final boolean right;
	private final IconAnchor anchor;
	private final StatText statText;
	private final Composite composite;
	private final Color buffColor;
	private final Color debuffColor;
	private final Color expiringColor;
	private final Color unchangedColor;
	private final int buffThreshold;
	private final int lowHp;
	private final int criticalHp;
	private final boolean showSelf;
	private final boolean partyStats;
	private final boolean showUnchanged;
	private final boolean showBuffs;
	private final boolean showDebuffs;

	/**
	 * Which stats are switched on, by {@link CombatStat} ordinal, since that is the order they are read
	 * and drawn in and a setting apiece is eight lookups otherwise.
	 */
	private final boolean[] enabled = new boolean[CombatStat.ALL.length];

	Settings(BoostIconConfig config)
	{
		size = config.size();
		drop = config.drop();
		right = config.iconSide() == IconSide.RIGHT;
		anchor = config.iconAnchor();
		statText = config.statText();
		composite = AlphaComposite.getInstance(AlphaComposite.SRC_OVER, opacity(config));
		buffColor = config.buffColor();
		debuffColor = config.debuffColor();
		expiringColor = config.expiringColor();
		unchangedColor = config.unchangedColor();
		buffThreshold = config.buffThreshold();
		lowHp = config.lowHp();
		criticalHp = config.criticalHp();
		showSelf = config.showSelf();
		partyStats = config.partyStats();
		showUnchanged = config.showUnchanged();
		showBuffs = config.showBuffs();
		showDebuffs = config.showDebuffs();

		for (int i = 0; i < enabled.length; i++)
		{
			enabled[i] = CombatStat.ALL[i].isEnabled(config);
		}
	}

	/**
	 * How solid everything is drawn, worked out here rather than per frame. Anything outside the settings
	 * panel could have put anything in the setting, so it is held to what it can be.
	 */
	private static float opacity(BoostIconConfig config)
	{
		return Math.max(0, Math.min(100, config.opacity())) / 100f;
	}

	int size()
	{
		return size;
	}

	int drop()
	{
		return drop;
	}

	/**
	 * Whether the icons go to the right of the health bar rather than the left of it.
	 */
	boolean right()
	{
		return right;
	}

	IconAnchor anchor()
	{
		return anchor;
	}

	StatText statText()
	{
		return statText;
	}

	Composite composite()
	{
		return composite;
	}

	Color buffColor()
	{
		return buffColor;
	}

	Color debuffColor()
	{
		return debuffColor;
	}

	Color expiringColor()
	{
		return expiringColor;
	}

	Color unchangedColor()
	{
		return unchangedColor;
	}

	int buffThreshold()
	{
		return buffThreshold;
	}

	int lowHp()
	{
		return lowHp;
	}

	int criticalHp()
	{
		return criticalHp;
	}

	boolean showSelf()
	{
		return showSelf;
	}

	boolean partyStats()
	{
		return partyStats;
	}

	boolean showUnchanged()
	{
		return showUnchanged;
	}

	boolean showBuffs()
	{
		return showBuffs;
	}

	boolean showDebuffs()
	{
		return showDebuffs;
	}

	boolean isEnabled(int stat)
	{
		return enabled[stat];
	}
}

package com.boosticon;

import java.awt.Color;

/**
 * A combat stat that is not where it would be with nothing acting on it, as of the last tick.
 *
 * What the stat reads as, meaning the number beside its icon and the colour that number is in, is worked
 * out here rather than while drawing, since it is the same for every frame of the tick the stat was read
 * on. The settings it was worked out from are kept beside it, and a different set means working it out
 * again, so a setting changed part way through a tick still shows on the very next frame.
 */
class StatChange
{
	private final CombatStat stat;
	private final int level;
	private final int change;

	/**
	 * The settings the two below were worked out from, if they have been worked out at all. Compared by
	 * which set it is rather than by what is in it, since a changed setting is always a new set.
	 */
	private Settings read;
	private String label;
	private Color color;

	StatChange(CombatStat stat, int level, int change)
	{
		this.stat = stat;
		this.level = level;
		this.change = change;
	}

	CombatStat getStat()
	{
		return stat;
	}

	/**
	 * The level the stat is at now, boost or drain included.
	 */
	int getLevel()
	{
		return level;
	}

	/**
	 * How far that is from the real level: positive for a boost, negative for a drain.
	 */
	int getChange()
	{
		return change;
	}

	/**
	 * The level with nothing acting on it, which for hitpoints and prayer is the full amount of them.
	 */
	int getRealLevel()
	{
		return level - change;
	}

	/**
	 * What is written beside the icon, or nothing where the settings ask for no number at all.
	 */
	String label(Settings settings)
	{
		read(settings);

		return label;
	}

	/**
	 * What colour that number is written in.
	 */
	Color color(Settings settings)
	{
		read(settings);

		return color;
	}

	private void read(Settings settings)
	{
		if (settings != read)
		{
			read = settings;
			label = labelFor(settings);
			color = colorFor(settings);
		}
	}

	private String labelFor(Settings settings)
	{
		if (stat.isPoints() && settings.statText() != StatText.NONE)
		{
			// What is left of them is the news, rather than how far off the full amount that is
			return String.valueOf(level);
		}

		switch (settings.statText())
		{
			case CHANGE:
				return change > 0 ? "+" + change : String.valueOf(change);
			case LEVEL:
				return String.valueOf(level);
			default:
				return null;
		}
	}

	/**
	 * The colours the game's own Boosts plugin uses, so a stat reads the same here as it does there:
	 * green while buffed, yellow once the buff is down to its last levels, red while debuffed.
	 */
	private Color colorFor(Settings settings)
	{
		if (stat.isPercent())
		{
			// A spec costs what it costs, so there is no amount of it that counts as being in trouble
			return settings.unchangedColor();
		}

		if (stat.isPoints())
		{
			return pointsColor(settings);
		}

		if (change == 0)
		{
			return settings.unchangedColor();
		}

		if (change < 0)
		{
			return settings.debuffColor();
		}

		int threshold = settings.buffThreshold();

		return threshold > 0 && change <= threshold ? settings.expiringColor() : settings.buffColor();
	}

	/**
	 * Hitpoints and prayer are coloured by how much of them is left rather than by which way they are
	 * off the full amount, so that a brew reads as plenty and a long fight reads as trouble.
	 */
	private Color pointsColor(Settings settings)
	{
		int full = getRealLevel();

		if (full < 1)
		{
			return settings.buffColor();
		}

		int left = level * 100 / full;

		if (left < settings.criticalHp())
		{
			return settings.debuffColor();
		}

		return left < settings.lowHp() ? settings.expiringColor() : settings.buffColor();
	}
}

